NAN = float("nan")

def closec(a, b, tol: float = 1e-12) -> bool:
    a = np.asarray(a).ravel()
    if a.size != len(b):
        print('size', a.size, len(b))
        return False
    for i in range(len(b)):
        if b[i] != b[i]:
            if a[i] == a[i]:
                print('expected nan at', i, a[i])
                return False
            continue
        if abs(a[i] - b[i]) > tol * max(1.0, abs(b[i])):
            print('mismatch at', i, a[i], b[i])
            return False
    return True


@test
def test_rk45():
    def f(t: float, y):
        return np.array([-0.5 * y[0] + y[1], -y[1] * 0.3 - y[0]])
    s = RK45(f, 0.0, np.array([1.0, 0.5]), 5.0, rtol=1e-6, atol=1e-9)
    n = 0
    mid = np.zeros(2)
    tm = 0.0
    while s.status == "running":
        s.step()
        n += 1
        if n == 5:
            d5 = s.dense_output()
            tm = 0.5 * (s.t_old + s.t)
            mid = d5(tm)
    assert closec(np.array([float(n), s.t, s.y[0], s.y[1], float(s.nfev)]), [24.0, 5.0, -0.017417363915210524, 0.14235084928425673, 146.0], 1e-9)
    d = s.dense_output()
    assert closec(d(4.8), [-0.049508756396375045, 0.1443508735680178], 1e-07)
    assert closec(d(np.array([4.7, 4.9])).ravel(), [-0.0667884536753835, -0.03301109773760457, 0.14285258792952266, 0.14413852110016814], 1e-07)
    assert closec(mid, [0.7047578220478535, -0.25390486136440854], 1e-07)
    assert closec(np.array([tm]), [np.float64(0.8196263254623789)], 1e-12)
test_rk45()
